import logging
import pathlib
import time
from typing import Any

logger = logging.getLogger("opencode-proxy.adr_generator")

ADR_TEMPLATE = """\
# ADR-{number:04d}: {title}

**Date:** {date}
**Status:** Draft

## Context
{context}

## Decision
{decision}

## Alternatives Considered
{alternatives}

## Consequences
- Positive: {positive}
- Negative / Trade-offs: {negative}

---
*Auto-generated by opencode-proxy ADR Generator — review and update before committing.*
"""

MAJOR_CHANGE_KEYWORDS = [
    "migrate", "migration", "refactor", "redesign", "replace", "rewrite",
    "new service", "new api", "new endpoint", "architecture", "database",
    "microservice", "breaking change", "deprecate", "remove", "upgrade",
]


def should_generate_adr(prompt: str) -> bool:
    """Detect if the user prompt represents a major architectural decision."""
    low = prompt.lower()
    return sum(1 for kw in MAJOR_CHANGE_KEYWORDS if kw in low) >= 1


def generate_adr_document(
    workspace_dir: str | pathlib.Path,
    title: str,
    context: str,
    decision: str,
    alternatives: str = "Not explicitly specified.",
    positive: str = "Improved codebase quality and maintainability.",
    negative: str = "Implementation effort required.",
) -> pathlib.Path | None:
    """Auto-generate an ADR markdown document in docs/adr/ of the workspace."""
    wpath = pathlib.Path(workspace_dir)
    adr_dir = wpath / "docs" / "adr"

    try:
        adr_dir.mkdir(parents=True, exist_ok=True)
    except Exception as exc:
        logger.warning("Could not create ADR directory: %s", exc)
        return None

    # Find next ADR number
    existing = sorted(adr_dir.glob("ADR-*.md"))
    number = len(existing) + 1
    date_str = time.strftime("%Y-%m-%d")

    content = ADR_TEMPLATE.format(
        number=number,
        title=title,
        date=date_str,
        context=context,
        decision=decision,
        alternatives=alternatives,
        positive=positive,
        negative=negative,
    )

    filename = adr_dir / f"ADR-{number:04d}-{title.lower().replace(' ', '-')[:50]}.md"
    try:
        filename.write_text(content, encoding="utf-8")
        logger.info("ADR Auto-Generated: %s", filename)
        return filename
    except Exception as exc:
        logger.warning("Failed writing ADR: %s", exc)
        return None
